impl Hint {
    pub fn new(name: impl Into<SharedString>, text: impl Into<SharedString>, cx: &App) -> Self {
        Self {
            name: name.into(),
            text: text.into(),
            body: None,
            marker: None,
            badge: None,
            focus: cx.focus_handle().tab_stop(true),
            bounds: Default::default(),
            presence: Slide::new(0.),
            open: false,
            epoch: 0,
            over: false,
